#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<int>a(n);
for(int i=0;i<n;++i)scanf("%d",&a[i]);
vector<int>st;int nxt=1;bool ok=true;
for(int x:a){
while(nxt<=x)st.push_back(nxt++);
if(!st.empty()&&st.back()==x)st.pop_back();
else{ok=false;break;}}
printf("%s\n",ok?"YES":"NO");return 0;}

